//! S6 state plugin — manages services via s6-rc on Artix/Chimera Linux.

use anyhow::{Context, Result};
use async_trait::async_trait;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;
use std::collections::HashMap;

/// Path to the s6-rc live directory
const S6_RC_LIVE: &str = "/run/s6-rc";

/// Run s6-rc with the standard live-dir prefix plus additional args.
async fn s6rc(args: &[&str]) -> Result<std::process::Output> {
    tokio::process::Command::new("s6-rc")
        .arg("-l")
        .arg(S6_RC_LIVE)
        .args(args)
        .output()
        .await
        .context("failed to run s6-rc")
}

/// Per-service configuration in the desired state.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct S6ServiceConfig {
    /// Desired state: "active" or "inactive"
    #[serde(skip_serializing_if = "Option::is_none")]
    pub state: Option<String>,
}

/// Top-level desired state for the s6 plugin.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct S6Config {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub services: Option<HashMap<String, S6ServiceConfig>>,
}

/// S6 state plugin — controls services through the `s6-rc` CLI.
pub struct S6StatePlugin;

impl S6StatePlugin {
    pub fn new() -> Self {
        Self
    }

    /// Return the names of all currently-up services.
    async fn list_running(&self) -> Result<Vec<String>> {
        // -a = show all supervised services (running only)
        let out = s6rc(&["-a", "list"]).await?;
        if !out.status.success() {
            return Ok(Vec::new());
        }
        Ok(String::from_utf8_lossy(&out.stdout)
            .lines()
            .map(|l| l.trim().to_string())
            .filter(|l| !l.is_empty())
            .collect())
    }

    /// Bring a service up; tolerate "already started" replies.
    async fn start_service(&self, name: &str) -> Result<()> {
        let out = s6rc(&["start", name]).await?;
        if out.status.success() {
            return Ok(());
        }
        let stderr = String::from_utf8_lossy(&out.stderr);
        // s6-rc exits non-zero if the service is already up
        if stderr.contains("already") {
            return Ok(());
        }
        anyhow::bail!("s6-rc start {} failed: {}", name, stderr);
    }

    /// Bring a service down; tolerate "already stopped" replies.
    async fn stop_service(&self, name: &str) -> Result<()> {
        let out = s6rc(&["stop", name]).await?;
        if out.status.success() {
            return Ok(());
        }
        let stderr = String::from_utf8_lossy(&out.stderr);
        if stderr.contains("already") {
            return Ok(());
        }
        anyhow::bail!("s6-rc stop {} failed: {}", name, stderr);
    }
}

impl Default for S6StatePlugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl StatePlugin for S6StatePlugin {
    fn name(&self) -> &str {
        "s6"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<op_state_store::PluginSchema> {
        Some(super::plugin_schema_defs::s6_plugin_schema())
    }

    /// The plugin is only available when the s6-rc live directory exists.
    fn is_available(&self) -> bool {
        std::path::Path::new(S6_RC_LIVE).exists()
    }

    fn unavailable_reason(&self) -> String {
        format!("s6-rc live directory not found at {S6_RC_LIVE}")
    }

    async fn query_current_state(&self) -> Result<Value> {
        let running = self.list_running().await?;
        let mut services = HashMap::new();
        for name in &running {
            services.insert(
                name.clone(),
                S6ServiceConfig {
                    state: Some("active".to_string()),
                },
            );
        }
        Ok(simd_json::serde::to_owned_value(S6Config {
            services: Some(services),
        })?)
    }

    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
        let current_config: S6Config = simd_json::serde::from_owned_value(current.clone())?;
        let desired_config: S6Config = simd_json::serde::from_owned_value(desired.clone())?;
        let mut actions = Vec::new();

        if let Some(desired_services) = &desired_config.services {
            for (name, desired_svc) in desired_services {
                let current_svc = current_config.services.as_ref().and_then(|s| s.get(name));
                if current_svc != Some(desired_svc) {
                    actions.push(StateAction::Modify {
                        resource: name.clone(),
                        changes: simd_json::serde::to_owned_value(desired_svc)?,
                    });
                }
            }
        }

        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
            },
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();

        for action in &diff.actions {
            if let StateAction::Modify { resource, changes } = action {
                let svc: S6ServiceConfig = simd_json::serde::from_owned_value(changes.clone())?;
                let result = match svc.state.as_deref() {
                    Some("active") => self.start_service(resource).await,
                    Some("inactive") => self.stop_service(resource).await,
                    _ => Ok(()),
                };
                match result {
                    Ok(()) => changes_applied.push(format!("Applied s6 config for {resource}")),
                    Err(e) => errors.push(format!("Failed to apply {resource}: {e}")),
                }
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, desired: &Value) -> Result<bool> {
        let current = self.query_current_state().await?;
        let current_config: S6Config = simd_json::serde::from_owned_value(current)?;
        let desired_config: S6Config = simd_json::serde::from_owned_value(desired.clone())?;
        Ok(current_config == desired_config)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        let current = self.query_current_state().await?;
        Ok(Checkpoint {
            id: format!("s6-{}", chrono::Utc::now().timestamp()),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: current,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
        let old: S6Config = simd_json::serde::from_owned_value(checkpoint.state_snapshot.clone())?;
        if let Some(services) = old.services {
            for (name, cfg) in services {
                match cfg.state.as_deref() {
                    Some("active") => {
                        let _ = self.start_service(&name).await;
                    }
                    Some("inactive") => {
                        let _ = self.stop_service(&name).await;
                    }
                    _ => {}
                }
            }
        }
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

//! S6-Systemctl Wrapper - Maps systemctl commands to s6 via D-Bus
//!
//! Provides a D-Bus interface that mirrors systemd's systemctl commands
//! but translates them to s6 operations. This allows tools and scripts
//! that expect systemctl to work on s6-based systems (Artix/Chimera).
//!
//! D-Bus interface: org.opdbus.v1.S6.Systemctl
//! Object path: /org/opdbus/v1/s6/systemctl
//!
//! Supported commands (mapped to s6 equivalents):
//! - start <service>    -> s6-rc -u change <service>
//! - stop <service>     -> s6-rc -d change <service>  
//! - restart <service>  -> s6-rc -d change <service> + s6-rc -u change <service>
//! - reload <service>   -> s6-svc -h /run/service/<service>
//! - enable <service>   -> s6-rc-bundle add <service> (create symlink)
//! - disable <service>  -> s6-rc-bundle delete <service>
//! - status <service>   -> s6-svstat /run/service/<service>
//! - is-active <service>-> s6-svstat check
//! - is-enabled <service>-> check if in s6-rc live
//! - list-units         -> s6-rc -a list (all active)
//! - list-unit-files    -> s6-rc -l list (all available)

use anyhow::{Context, Result};
use std::collections::HashMap;
use std::path::Path;
use std::process::Stdio;
use tokio::process::Command;
use tracing::{debug, error, info, warn};
use zbus::interface;

/// S6 base paths
const S6_RC_LIVE: &str = "/run/s6-rc";
const S6_SERVICE_DIR: &str = "/run/service";
const S6_RC_BUNDLE: &str = "/etc/s6-rc/bundle";

/// D-Bus service for s6-systemctl wrapper
pub struct S6SystemctlService;

impl S6SystemctlService {
    pub fn new() -> Self {
        Self
    }

    /// Check if s6 is available on this system
    fn is_s6_available() -> bool {
        Path::new(S6_RC_LIVE).exists() || Path::new(S6_SERVICE_DIR).exists()
    }

    /// Run s6-rc with given arguments
    async fn s6rc(&self, args: &[&str]) -> Result<(bool, String, String)> {
        let mut cmd = Command::new("s6-rc");

        // Use live directory if it exists
        if Path::new(S6_RC_LIVE).exists() {
            cmd.arg("-l").arg(S6_RC_LIVE);
        }

        cmd.args(args);

        debug!("Running s6-rc with args: {:?}", args);

        let output = cmd
            .output()
            .await
            .context("failed to run s6-rc")?;

        let success = output.status.success();
        let stdout = String::from_utf8_lossy(&output.stdout).to_string();
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();

        if !success {
            debug!("s6-rc failed: stderr={}, stdout={}", stderr, stdout);
        }

        Ok((success, stdout, stderr))
    }

    /// Run s6-svc for service control
    async fn s6svc(&self, service: &str, signal: &str) -> Result<(bool, String)> {
        let service_path = format!("{}/{}", S6_SERVICE_DIR, service);

        if !Path::new(&service_path).exists() {
            return Ok((false, format!("Service {} not found at {}", service, service_path)));
        }

        let output = Command::new("s6-svc")
            .arg(signal)
            .arg(&service_path)
            .output()
            .await
            .context("failed to run s6-svc")?;

        let success = output.status.success();
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();

        Ok((success, stderr))
    }

    /// Run s6-svstat to get service status
    async fn s6svstat(&self, service: &str) -> Result<HashMap<String, String>> {
        let service_path = format!("{}/{}", S6_SERVICE_DIR, service);

        let output = Command::new("s6-svstat")
            .arg(&service_path)
            .output()
            .await
            .context("failed to run s6-svstat")?;

        let mut result = HashMap::new();

        if output.status.success() {
            let stdout = String::from_utf8_lossy(&output.stdout);
            // Parse s6-svstat output: "up (pid 1234) 12345 seconds"
            // or "down 123 seconds"

            if stdout.starts_with("up") {
                result.insert("ActiveState".to_string(), "active".to_string());
                result.insert("SubState".to_string(), "running".to_string());

                // Extract PID if present
                if let Some(pid_start) = stdout.find("pid ") {
                    let pid_part = &stdout[pid_start + 4..];
                    if let Some(pid_end) = pid_part.find(')') {
                        result.insert("MainPID".to_string(), pid_part[..pid_end].to_string());
                    }
                }
            } else {
                result.insert("ActiveState".to_string(), "inactive".to_string());
                result.insert("SubState".to_string(), "dead".to_string());
                result.insert("MainPID".to_string(), "0".to_string());
            }

            // Extract uptime
            if let Some(sec_start) = stdout.find("seconds") {
                let before = &stdout[..sec_start];
                if let Some(last_space) = before.rfind(' ') {
                    result.insert("Uptime".to_string(), before[last_space + 1..sec_start].trim().to_string());
                }
            }
        } else {
            result.insert("ActiveState".to_string(), "unknown".to_string());
            result.insert("SubState".to_string(), "not-found".to_string());
        }

        Ok(result)
    }

    /// Check if service is enabled (in the current bundle)
    async fn is_enabled(&self, service: &str) -> bool {
        // Check if service is in the s6-rc database
        if let Ok((success, stdout, _)) = self.s6rc(&["list"]).await {
            if success {
                return stdout.lines().any(|line| line.trim() == service);
            }
        }
        false
    }
}

impl Default for S6SystemctlService {
    fn default() -> Self {
        Self::new()
    }
}

#[interface(name = "org.opdbus.v1.S6.Systemctl")]
impl S6SystemctlService {
    /// Start a service (systemctl start equivalent)
    async fn start(&self, service: &str) -> (bool, String) {
        info!("s6-systemctl: starting {}", service);

        match self.s6rc(&["-u", "change", service]).await {
            Ok((success, stdout, stderr)) => {
                if success || stderr.contains("already up") {
                    (true, format!("Started {} successfully", service))
                } else {
                    (false, format!("Failed to start {}: {}", service, stderr))
                }
            }
            Err(e) => (false, format!("Error starting {}: {}", service, e)),
        }
    }

    /// Stop a service (systemctl stop equivalent)
    async fn stop(&self, service: &str) -> (bool, String) {
        info!("s6-systemctl: stopping {}", service);

        match self.s6rc(&["-d", "change", service]).await {
            Ok((success, stdout, stderr)) => {
                if success || stderr.contains("already down") {
                    (true, format!("Stopped {} successfully", service))
                } else {
                    (false, format!("Failed to stop {}: {}", service, stderr))
                }
            }
            Err(e) => (false, format!("Error stopping {}: {}", service, e)),
        }
    }

    /// Restart a service (systemctl restart equivalent)
    async fn restart(&self, service: &str) -> (bool, String) {
        info!("s6-systemctl: restarting {}", service);

        // First stop
        let (stop_ok, stop_msg) = self.stop(service).await;
        if !stop_ok && !stop_msg.contains("already down") {
            warn!("s6-systemctl: restart stop phase failed: {}", stop_msg);
        }

        // Then start
        let (start_ok, start_msg) = self.start(service).await;
        if start_ok {
            (true, format!("Restarted {} successfully", service))
        } else {
            (false, format!("Failed to restart {}: {}", service, start_msg))
        }
    }

    /// Reload a service (systemctl reload equivalent)
    async fn reload(&self, service: &str) -> (bool, String) {
        info!("s6-systemctl: reloading {}", service);

        match self.s6svc(service, "-h").await {
            Ok((success, stderr)) => {
                if success {
                    (true, format!("Reloaded {} successfully", service))
                } else {
                    (false, format!("Failed to reload {}: {}", service, stderr))
                }
            }
            Err(e) => (false, format!("Error reloading {}: {}", service, e)),
        }
    }

    /// Get service status (systemctl status equivalent)
    /// Returns JSON with: ActiveState, SubState, MainPID, Uptime
    async fn status(&self, service: &str) -> String {
        debug!("s6-systemctl: getting status for {}", service);

        match self.s6svstat(service).await {
            Ok(mut status) => {
                // Add enabled status
                let enabled = self.is_enabled(service).await;
                status.insert("UnitFileState".to_string(), 
                    if enabled { "enabled".to_string() } else { "disabled".to_string() });

                match simd_json::to_string(&status) {
                    Ok(json) => json,
                    Err(_) => format!("{{\"ActiveState\":\"unknown\",\"error\":\"json error\"}}"),
                }
            }
            Err(e) => format!("{{\"ActiveState\":\"unknown\",\"error\":\"{}\"}}", e),
        }
    }

    /// Check if service is active (systemctl is-active equivalent)
    async fn is_active(&self, service: &str) -> &str {
        match self.s6svstat(service).await {
            Ok(status) => {
                if status.get("ActiveState").map(|s| s == "active").unwrap_or(false) {
                    "active"
                } else {
                    "inactive"
                }
            }
            Err(_) => "unknown",
        }
    }

    /// Check if service is enabled (systemctl is-enabled equivalent)
    async fn is_enabled_method(&self, service: &str) -> &str {
        if self.is_enabled(service).await {
            "enabled"
        } else {
            "disabled"
        }
    }

    /// Enable a service (systemctl enable equivalent)
    /// Note: s6 uses bundles, this creates the necessary symlinks
    async fn enable(&self, service: &str) -> (bool, String) {
        info!("s6-systemctl: enabling {}", service);

        // For s6, enabling typically means adding to the default bundle
        // This is a simplified implementation
        let bundle_path = format!("{}/default/contents.d/{}", S6_RC_BUNDLE, service);

        match tokio::fs::metadata(&bundle_path).await {
            Ok(_) => (true, format!("{} is already enabled", service)),
            Err(_) => {
                // Try to add to bundle using s6-rc-bundle
                match self.s6rc(&["-u", "change", service]).await {
                    Ok((success, _, _)) => {
                        if success {
                            (true, format!("Enabled {} successfully", service))
                        } else {
                            (true, format!("Enabled {} (may require manual s6-rc-bundle setup)", service))
                        }
                    }
                    Err(e) => (false, format!("Error enabling {}: {}", service, e)),
                }
            }
        }
    }

    /// Disable a service (systemctl disable equivalent)
    async fn disable(&self, service: &str) -> (bool, String) {
        info!("s6-systemctl: disabling {}", service);

        // First stop the service
        let _ = self.stop(service).await;

        // Note: Full disable in s6 requires bundle manipulation
        // This is a simplified version
        (true, format!("Disabled {} (stopped service, manual bundle cleanup may be needed)", service))
    }

    /// List all active services (systemctl list-units equivalent)
    async fn list_units(&self) -> String {
        debug!("s6-systemctl: listing units");

        match self.s6rc(&["-a", "list"]).await {
            Ok((success, stdout, _)) => {
                if success {
                    let services: Vec<HashMap<String, String>> = stdout
                        .lines()
                        .filter(|l| !l.is_empty())
                        .map(|name| {
                            let mut map = HashMap::new();
                            map.insert("unit".to_string(), name.to_string());
                            map.insert("load".to_string(), "loaded".to_string());
                            map.insert("active".to_string(), "active".to_string());
                            map.insert("sub".to_string(), "running".to_string());
                            map.insert("description".to_string(), format!("s6 service {}", name));
                            map
                        })
                        .collect();

                    match simd_json::to_string(&services) {
                        Ok(json) => json,
                        Err(_) => "[]".to_string(),
                    }
                } else {
                    "[]".to_string()
                }
            }
            Err(_) => "[]".to_string(),
        }
    }

    /// Get daemon status
    async fn daemon_status(&self) -> &str {
        if Self::is_s6_available() {
            "running"
        } else {
            "not-available"
        }
    }
}

/// Run the s6-systemctl D-Bus service
pub async fn run_s6_systemctl_service() -> Result<()> {
    let conn = zbus::connection::Connection::system()
        .await
        .context("Failed to connect to system D-Bus")?;

    conn.object_server()
        .at("/org/opdbus/v1/s6/systemctl", S6SystemctlService::new())
        .await
        .context("Failed to register s6-systemctl object")?;

    conn.request_name("org.opdbus.v1.S6.Systemctl")
        .await
        .context("Failed to request bus name")?;

    info!("S6-Systemctl D-Bus service registered at org.opdbus.v1.S6.Systemctl");

    // Keep connection alive
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

//! Default plugin loader - auto-loads essential plugins
//!
//! This module defines which plugins are loaded by default when the system starts.
//! Plugins can be enabled/disabled via configuration.
//!
//! ## Schema Validation
//!
//! Plugins are validated against JSON schema files at runtime.
//! If a schema file is missing in strict mode, the plugin will be rejected.
//! Schema files are loaded from `schemas/plugin/{name}.json`.
//!
//! ## Canonical Path Enforcement
//!
//! All plugins must use canonical D-Bus paths:
//! - Path: `/org/opdbus/v1/plugin/plugins/{name}`
//! - Interface: `org.opdbus.v1.Plugin.Plugins.{Name}`
//!
//! Legacy paths are deprecated and will be rejected.

use anyhow::{anyhow, Result};
use op_state_store::StateStore;
use simd_json::prelude::*;
use std::sync::Arc;

use crate::schema_loader::SchemaLoader;

use crate::state_plugins::{
    AdcPlugin, AgentConfigPlugin, AntigravityChatPlugin, AntigravityPlugin, BtrfsPlugin,
    CognitiveMcpPlugin, CompactMcpPlugin, ConfigPlugin, CronPlugin, CtlPlaneChatbotPlugin,
    DnsResolverPlugin, EndpointPlugin, FactoryPlugin, Fail2banPlugin, FreeDesktopPlugin,
    FullSystemPlugin, GcloudAdcPlugin, HardwarePlugin, IncusPlugin, KeypairPlugin, KeyringPlugin,
    KnowledgePlugin, Login1Plugin, LxcPlugin, MailServerPlugin, McpStatePlugin, MemoryPlugin,
    NetStatePlugin, NetmakerConfig, NetmakerPlugin, OpenFlowPlugin, OvsBridgePlugin, OvsdbDaemonPlugin,
    PackageKitPlugin, PciDeclPlugin, PrivacyRouterPlugin, PrivacyRoutesPlugin, ProcfsPlugin,
    ProxmoxPlugin, ProxyServerPlugin, RovsCommandsPlugin, RtnetlinkPlugin, S6StatePlugin,
    SchemaRendererPlugin, ServicePlugin, SessDeclPlugin, SoftwarePlugin, UnixSocketPlugin,
    UsersPlugin, WebUiPlugin, WireGuardPlugin, WorkflowsPlugin, ZeroclawPlugin,
};
use crate::AutoPlugin;

/// Default plugin loader configuration
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct PluginRegistryConfig {
    /// Auto-load plugins on startup
    #[serde(default = "default_auto_load")]
    pub auto_load: Vec<String>,

    /// Plugin-specific configurations
    #[serde(default)]
    pub plugin_configs: std::collections::HashMap<String, simd_json::OwnedValue>,
}

fn default_auto_load() -> Vec<String> {
    let wg_only = std::env::var("OP_DBUS_WG_ONLY")
        .ok()
        .map(|v| {
            let l = v.to_lowercase();
            !(l == "0" || l == "false" || l == "no")
        })
        .unwrap_or(false);

    if wg_only {
        return vec![
            "zeroclaw".to_string(),
            "config".to_string(),
            "service".to_string(),
            "s6".to_string(),
            "net".to_string(),
            "rtnetlink".to_string(),
            "procfs".to_string(),
            "wireguard".to_string(),
            "agent_config".to_string(),
        ];
    }

    vec![
        "mcp".to_string(),
        "zeroclaw".to_string(),
        "cognitive_mcp".to_string(),
        "compact_mcp".to_string(),
        "config".to_string(),
        "s6".to_string(),
        "incus".to_string(),
        "mail_server".to_string(),
        "unix_socket".to_string(),
        "net".to_string(),
        "openflow".to_string(),
        "ovsdb_bridge".to_string(),
        "ovsdb_daemon".to_string(),
        "privacy_router".to_string(),
        "rovs_commands".to_string(),
        "privacy_routes".to_string(),
        "procfs".to_string(),
        "rtnetlink".to_string(),
        "agent_config".to_string(),
    ]
}

impl Default for PluginRegistryConfig {
    fn default() -> Self {
        Self {
            auto_load: default_auto_load(),
            plugin_configs: std::collections::HashMap::new(),
        }
    }
}

/// Default plugin loader.
///
/// This is intentionally not the authoritative plugin catalog. Its job is to
/// instantiate the built-in plugin implementations so the real catalog path can
/// persist their canonical plugin documents during registration.
pub struct DefaultPluginRegistry {
    config: PluginRegistryConfig,
    state_store: Arc<dyn StateStore>,
    schema_loader: SchemaLoader,
}

impl DefaultPluginRegistry {
    /// Create a new plugin loader
    pub fn new(state_store: Arc<dyn StateStore>) -> Self {
        Self {
            config: PluginRegistryConfig::default(),
            state_store,
            schema_loader: SchemaLoader::new("schemas/plugin"),
        }
    }

    /// Create with custom schema directory
    pub fn with_schema_dir(
        state_store: Arc<dyn StateStore>,
        schema_dir: impl Into<std::path::PathBuf>,
    ) -> Self {
        Self {
            config: PluginRegistryConfig::default(),
            state_store,
            schema_loader: SchemaLoader::new(schema_dir),
        }
    }

    /// Validate a plugin has a valid schema file
    ///
    /// Returns Ok(()) if schema exists and is valid
    /// Returns Err if schema is missing or invalid (in strict mode)
    pub async fn validate_plugin_schema(&self, plugin_name: &str) -> Result<()> {
        match self.schema_loader.load_schema(plugin_name).await? {
            Some(_) => Ok(()),
            None => Err(anyhow!(
                "Plugin '{}' has no valid schema file. Expected: schemas/plugin/{}.json",
                plugin_name,
                plugin_name
            )),
        }
    }

    /// Check if a schema file exists for a plugin
    pub async fn schema_exists(&self, plugin_name: &str) -> bool {
        self.schema_loader.schema_exists(plugin_name).await
    }

    /// Create with custom configuration
    pub fn with_config(state_store: Arc<dyn StateStore>, config: PluginRegistryConfig) -> Self {
        Self {
            config,
            state_store,
            schema_loader: SchemaLoader::new("schemas/plugin"),
        }
    }

    /// Create with custom configuration and schema directory
    pub fn with_config_and_schema_dir(
        state_store: Arc<dyn StateStore>,
        config: PluginRegistryConfig,
        schema_dir: impl Into<std::path::PathBuf>,
    ) -> Self {
        Self {
            config,
            state_store,
            schema_loader: SchemaLoader::new(schema_dir),
        }
    }

    /// Resolve user/request-facing plugin references into canonical loader names.
    ///
    /// Supports direct names, aliases, and CANONICAL projection paths like
    /// `/org/opdbus/v1/plugin/plugins/<plugin>/...`.
    ///
    /// Legacy paths like `/opdbus/v1/plugins/...` are NO LONGER SUPPORTED.
    /// Use canonical paths as defined in `crate::canonical`.
    pub fn resolve_requested_plugin_name(requested: &str) -> Result<String> {
        let trimmed = requested.trim();
        if trimmed.is_empty() {
            return Err(anyhow!("Plugin identifier cannot be empty"));
        }

        let from_path = Self::extract_plugin_name_from_projection_path(trimmed).unwrap_or(trimmed);
        let normalized = from_path
            .trim()
            .trim_matches('/')
            .replace('-', "_")
            .to_lowercase();

        let canonical = match normalized.as_str() {
            "network" => "net",
            "systemd" | "dinit" | "service_s6" => "s6",
            "web_ui" | "webui" => "web_ui",
            "mail" | "mailserver" => "mail_server",
            "privacyroutes" => "privacy_routes",
            "privacyrouter" => "privacy_router",
            "ovsbridge" => "ovsdb_bridge",
            "rtnet" => "rtnetlink",
            "sessdecl" => "sess_decl",
            other => other,
        };

        Ok(canonical.to_string())
    }

    fn extract_plugin_name_from_projection_path(requested: &str) -> Option<&str> {
        // CANONICAL PATH ONLY: /org/opdbus/v1/plugin/plugins/{name}
        // Legacy paths are deprecated and will be rejected
        use crate::canonical::PLUGIN_BASE_PATH;

        // Check canonical path prefix
        if let Some(rest) = requested.strip_prefix(PLUGIN_BASE_PATH) {
            return rest
                .trim_start_matches('/')
                .split('/')
                .find(|segment| !segment.is_empty());
        }

        // Also accept the /org/opdbus/v1/plugin/plugins/ prefix without leading slash
        if let Some(rest) = requested.strip_prefix(&PLUGIN_BASE_PATH[1..]) {
            return rest
                .trim_start_matches('/')
                .split('/')
                .find(|segment| !segment.is_empty());
        }

        None
    }

    /// Load all auto-load plugins
    pub async fn load_default_plugins(&self) -> Result<Vec<Arc<dyn op_state::StatePlugin>>> {
        let mut plugins: Vec<Arc<dyn op_state::StatePlugin>> = Vec::new();

        for plugin_name in &self.config.auto_load {
            match self.load_plugin(plugin_name).await {
                Ok(plugin) => {
                    if !plugin.is_available() {
                        tracing::info!(
                            "Skipping unavailable plugin {}: {}",
                            plugin_name,
                            plugin.unavailable_reason()
                        );
                        continue;
                    }
                    tracing::info!("✅ Loaded plugin: {}", plugin_name);
                    plugins.push(plugin);
                }
                Err(e) => {
                    tracing::warn!("⚠️ Failed to load plugin {}: {}", plugin_name, e);
                }
            }
        }

        tracing::info!("📦 Loaded {} plugins", plugins.len());
        Ok(plugins)
    }

