}

#[derive(Serialize)]
pub struct SystemInfo {
    pub hostname: String,
    pub kernel: String,
    pub uptime_secs: u64,
    pub load_average: [f64; 3],
    pub memory_total_mb: u64,
    pub memory_used_mb: u64,
    pub memory_percent: f64,
    pub cpu_count: usize,
    pub cpu_usage: f32,
}

#[derive(Serialize)]
pub struct ToolsInfo {
